root.script:
System.print("Setting up keypress listener...")
// Listen for keypress events on the document document.addEventListener("keypress", Fn.new { |event| System.print("KEYPRESS EVENT RECEIVED!") System.print(" Type: " + event["type"]) System.print(" Key: " + event["key"]) System.print(" Target: " + event["target"].toString) })
System.print("Event listener registered successfully!") System.print("Press any key to test...")
